mapper.select:
SELECT n.notice_id AS noticeId, n.title AS title, n.notice_type AS noticeType, COALESCE(n.published_at, n.created_at) AS baseDateTime, n.is_pinned AS isPinned, n.author_org_name AS authorOrgName, n.author_employee_name AS authorEmployeeName FROM notice n WHERE n.is_published = TRUE
AND n.notice_type = #{noticeType}
ORDER BY n.is_pinned DESC, COALESCE(n.published_at, n.created_at) DESC, n.notice_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT n.notice_id AS noticeId, n.title AS title, n.notice_type AS noticeType, COALESCE(n.published_at, n.created_at) AS baseDateTime, n.is_pinned AS isPinned, n.author_org_name AS authorOrgName, n.author_employee_name AS authorEmployeeName FROM notice n WHERE n.is_published = TRUE AND n.author_employee_id = #{authorEmployeeId}
AND n.notice_type = #{noticeType}
ORDER BY n.is_pinned DESC, COALESCE(n.published_at, n.created_at) DESC, n.notice_id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM notice n
WHERE n.is_published = TRUE
  AND n.author_employee_id = #{authorEmployeeId}

  AND n.notice_type = #{noticeType}
